-- V81: Master L.E.A.D Leadership Test (15 questions) from user-provided embedded JSON.
-- The existing RLS/RPC contracts remain the authoritative leader/super_admin access control.
begin;

insert into public.leadership_tests (test_key, intro_disclaimer, questions, results, is_active)
values (
  'leadership_style_v1',
  $v81json${"title":"Khám Phá Phong Cách Lãnh Đạo Nội Tại","content":"Chào bạn, một Người Dẫn Dắt. Trong ngành Bảo hiểm Nhân thọ, không có một phong cách lãnh đạo nào là 'tốt nhất' hay 'đúng chuẩn' cho mọi tình huống. Mỗi chúng ta là một cá thể độc bản. Bài trắc nghiệm này không sinh ra để phán xét bạn. Nó là một tấm gương phản chiếu, được chắt lọc từ kinh nghiệm thực chiến xương máu của nghề Bảo hiểm. Hãy chọn đáp án bạn thấy thoải mái và 'giống mình' nhất lúc này để nhận diện thế mạnh tự nhiên của bản thân nhé!"}$v81json$::jsonb,
  $v81json$[{"id":1,"scenario":"Một TVV kỳ cựu trong nhóm của bạn tháng này bị rớt 2 hợp đồng liên tiếp phút chót. Bạn ấy mất năng lượng, trễ deadline nộp báo cáo và hay than vãn. Hướng tiếp cận ưu tiên của bạn là:","options":[{"text":"Hẹn đi cà phê, lắng nghe xem bạn ấy đang gặp vướng mắc tâm lý gì sau 2 cú rớt deal vừa rồi để xoa dịu.","trait":"Nurturer"},{"text":"Ngồi lại rà soát hồ sơ 2 ca rớt deal kia, phân tích lý do khách hàng từ chối ở khâu nào để rút kinh nghiệm.","trait":"Architect"},{"text":"Kể lại một lần chính mình bị khách hàng từ chối đau điếng ra sao, rủ bạn ấy tuần này cùng đi gặp một khách mới.","trait":"Visionary"},{"text":"Hỏi bạn ấy: 'Hai ca vừa rồi rớt khiến em học được bài học lớn nhất là gì? Nếu làm lại, em sẽ đổi bước nào?'","trait":"Coach"}]},{"id":2,"scenario":"Công ty vừa ra Memo thi đua tháng mới với chỉ tiêu FYP cực kỳ thách thức. Một đại lý nhắn tin vào group Zalo của Team: 'Chỉ tiêu trên trời thế này thì ai mà chạy nổi!'. Bạn sẽ:","options":[{"text":"Nhắn tin riêng áp dụng khung SBI: 'Chị thấy em nhắn vậy trong group làm các bạn mới hoang mang. Mình cùng tháo gỡ nhé'.","trait":"Coach"},{"text":"Gọi riêng hỏi thăm dạo này gia đình có việc gì áp lực không mà tâm trạng lại dễ bức xúc như vậy.","trait":"Nurturer"},{"text":"Nhắc nhở nhẹ nhàng nội quy group, sau đó gửi một file Excel hướng dẫn chia nhỏ chỉ tiêu FYP ra từng tuần.","trait":"Architect"},{"text":"Gửi ngay vào group một bảng vinh danh hoặc một phần thưởng nóng do bạn tài trợ để kích tinh thần chiến đấu.","trait":"Visionary"}]},{"id":3,"scenario":"Một đại lý mới (Rookie) than vãn: 'Em đăng bài thẻ sức khỏe lên Facebook cả tháng nay mà chẳng ai thèm hỏi mua, nản quá'. Bạn sẽ:","options":[{"text":"Chuyển ngay cho bạn ấy một bộ content mẫu và kịch bản chat chốt sale tốt để copy làm theo.","trait":"Architect"},{"text":"Hỏi ngược lại: 'Mục tiêu bài đăng của em là chốt khách ngay hay xây dựng nhân hiệu? Tâm lý khách trên mạng là gì?'","trait":"Coach"},{"text":"Bảo bạn ấy: 'Làm BHNT tháng đầu ai cũng vắng khách, quan trọng là kiên trì. Mai đi cùng chị gặp khách thực tế nhé!'.","trait":"Visionary"},{"text":"Bảo bạn ấy tạm dừng đăng bài vài ngày, rủ đi ăn trưa để làm công tác tư tưởng, xả bớt cảm giác chán nản.","trait":"Nurturer"}]},{"id":4,"scenario":"Phỏng vấn ứng viên tiềm năng: Họ có năng lượng cao, giao tiếp tốt nhưng CV cho thấy nhảy việc 3 lần trong 2 năm qua. Bạn ưu tiên:","options":[{"text":"Yêu cầu họ chứng minh bằng các con số KPI cụ thể đã đạt được ở công ty cũ.","trait":"Architect"},{"text":"Hỏi sâu về lý do rời đi ở các công ty cũ, thể hiện sự đồng cảm với khó khăn của họ.","trait":"Nurturer"},{"text":"Đưa ngay một tình huống xử lý từ chối hóc búa và yêu cầu roleplay ngay tại chỗ để thử lửa.","trait":"Visionary"},{"text":"Hỏi: 'Theo em, điều gì ở một công việc sẽ khiến em muốn gắn bó lâu dài từ 3-5 năm tới?'","trait":"Coach"}]},{"id":5,"scenario":"Khách hàng VIP gọi điện mắng vốn TVV xối xả vì quy trình bồi thường chậm trễ. TVV hoảng loạn gọi nhờ bạn giúp đỡ.","options":[{"text":"Rà soát ngay điều khoản hợp đồng và quy trình phòng bồi thường để chuẩn bị bằng chứng logic giải thích.","trait":"Architect"},{"text":"Trấn an TVV: 'Em bình tĩnh, không sao cả, để chị nghe máy xử lý cho', xoa dịu TVV là ưu tiên số 1.","trait":"Nurturer"},{"text":"Gọi thẳng cho khách VIP, dùng uy tín của cấp Quản lý để xin lỗi và cam kết xử lý ngay.","trait":"Visionary"},{"text":"Hướng dẫn TVV: 'Nếu em là khách đang bực mình, em muốn nghe câu gì nhất? Hãy gọi lại và nói câu đó'.","trait":"Coach"}]},{"id":6,"scenario":"Gần đây các buổi họp Team hàng tuần (Weekly Meeting) trở nên nhàm chán, TVV viện lý do vắng mặt nhiều. Bạn sẽ làm mới bằng cách:","options":[{"text":"Siết kỷ luật, lập bảng điểm danh rõ ràng và chuẩn bị agenda họp cực kỳ chi tiết, súc tích.","trait":"Architect"},{"text":"Nhắn riêng hỏi vài TVV xem họ thực sự muốn nghe điều gì, biến buổi họp thành nơi tâm tình, xả stress.","trait":"Nurturer"},{"text":"Tổ chức mini-game thi thuyết trình sản phẩm, có phần thưởng tiền mặt trao tay để đẩy năng lượng lên đỉnh.","trait":"Visionary"},{"text":"Dành 15 phút đầu giờ để cả team brainstorm: 'Làm thế nào để buổi họp sáng thứ 2 đáng giá hơn?'","trait":"Coach"}]},{"id":7,"scenario":"Một đại lý nói rằng họ không có thời gian để gọi đủ 20 cuộc cold-call mỗi ngày như quy định của Team.","options":[{"text":"Mở file time-blocking, cùng sắp xếp lại lịch để tìm ra 2 tiếng đồng hồ cố định mỗi ngày chỉ dành cho việc gọi.","trait":"Architect"},{"text":"Đồng cảm rằng gọi lạnh rất áp lực, bảo họ tạm giảm xuống 5 cuộc/ngày hoặc chuyển sang chăm sóc khách cũ.","trait":"Nurturer"},{"text":"Kéo ghế ngồi cạnh, bật loa ngoài tự tay thực hiện 5 cuộc gọi lạnh chốt hẹn ngay trước mặt họ để làm gương.","trait":"Visionary"},{"text":"Hỏi: 'Theo em, điều gì đang cản trở em cầm điện thoại lên? Nếu gọi đủ 20 cuộc, thu nhập của em sẽ đổi khác ra sao?'","trait":"Coach"}]},{"id":8,"scenario":"Ngày đầu tháng, bước quan trọng nhất của bạn khi làm việc với đội ngũ để lên mục tiêu là gì?","options":[{"text":"Phân tích báo cáo tháng trước, tính tỷ lệ chuyển đổi để áp chỉ tiêu FYP cụ thể cho từng người.","trait":"Architect"},{"text":"Tâm sự 1:1, hỏi thăm tháng này họ cần thu nhập bao nhiêu để lo cho gia đình, lấy đó làm động lực.","trait":"Nurturer"},{"text":"Công bố một mục tiêu lớn cho Đội, hô hào quyết tâm và hứa khao cả team đi du lịch nếu đạt 120% target.","trait":"Visionary"},{"text":"Yêu cầu mỗi cá nhân tự viết ra con số họ muốn đạt và tự trình bày kế hoạch chi tiết để đạt con số đó.","trait":"Coach"}]},{"id":9,"scenario":"Một 'Ngôi sao bán hàng' mang về doanh số lớn, nhưng bắt đầu tỏ ra kiêu ngạo, đi trễ về sớm, phá vỡ kỷ luật chung.","options":[{"text":"Kiên quyết áp dụng nội quy. Doanh số quan trọng nhưng kỷ luật phải công bằng cho tất cả.","trait":"Architect"},{"text":"Gặp gỡ ôn tồn, công nhận công lao nhưng khéo léo chia sẻ rằng thái độ của họ đang làm anh em khác chạnh lòng.","trait":"Nurturer"},{"text":"Giao cho họ một mục tiêu khó hơn (MDRT/COT) để họ bận rộn chinh phục đỉnh cao mới, quên đi cái tôi hiện tại.","trait":"Visionary"},{"text":"Hỏi họ: 'Với tư cách là người giỏi nhất team, em muốn xây dựng hình ảnh đàn anh/đàn chị thế nào trong mắt các bạn mới?'","trait":"Coach"}]},{"id":10,"scenario":"Chỉ còn 3 ngày là chốt số tháng, toàn Đội mới đạt 70% chỉ tiêu. Không khí rất căng thẳng. Bạn sẽ:","options":[{"text":"Lọc lại data khách hàng 'pending', tính toán chính xác cần chốt thêm mấy HĐ, chia task gấp cho từng người.","trait":"Architect"},{"text":"Nhắc nhở mọi người chú ý sức khỏe, đừng vì cố ép số mà làm sai quy trình hay ảnh hưởng khách hàng.","trait":"Nurturer"},{"text":"Tuyên bố 'Xõa hết mình', xách cặp đi cùng anh em đến gặp khách 12 tiếng/ngày để hỗ trợ chốt deal đến phút 89.","trait":"Visionary"},{"text":"Gom team họp 15 phút, hỏi: 'Còn 3 ngày. Mỗi người có thể cam kết làm 1 hành động cụ thể nào ngay bây giờ để đảo ngược tình thế?'","trait":"Coach"}]},{"id":11,"scenario":"Một TVV trẻ rất tiềm năng xin nghỉ việc với lý do: 'Gia đình em phản đối gay gắt quá, nói làm bảo hiểm là lừa đảo'. Bạn xử lý sao?","options":[{"text":"Đưa ra các dẫn chứng luật pháp, bài báo uy tín về bảo hiểm để bạn ấy mang về thuyết phục lại gia đình.","trait":"Architect"},{"text":"Lắng nghe những áp lực bạn ấy đang chịu ở nhà, đồng cảm và khuyên bạn nên từ từ chứng minh bằng hành động thay vì cãi lại.","trait":"Nurturer"},{"text":"Kể câu chuyện ngày xưa gia đình mình cũng từng cấm cản ra sao, và mình đã dùng tháng lương 50 triệu đầu tiên để chứng minh thế nào.","trait":"Visionary"},{"text":"Hỏi bạn ấy: 'Lý do ban đầu em chọn công việc này là gì? Sự phản đối của gia đình có thay đổi được giá trị công việc em đang tin tưởng không?'","trait":"Coach"}]},{"id":12,"scenario":"Công ty đang chạy chiến dịch bán chéo (Cross-sell) Phi nhân thọ (thẻ sức khỏe độc lập), nhưng team bạn bị 'loạn' và bỏ bê hợp đồng Nhân thọ chính. Bạn sẽ:","options":[{"text":"Lập lại bảng tính hoa hồng, chỉ ra cho team thấy tập trung vào Nhân thọ mang lại thu nhập cốt lõi tốt hơn hẳn Phi nhân thọ.","trait":"Architect"},{"text":"Nhẹ nhàng nhắc nhở trong nhóm, không gây áp lực quá gắt vì có thể team đang muốn kiếm 'tiền nhanh' để trang trải cuộc sống.","trait":"Nurturer"},{"text":"Chốt ngay một hợp đồng Nhân thọ lớn trong tuần, show lên group để kéo sự chú ý của team quay lại đường đua chính.","trait":"Visionary"},{"text":"Hỏi team: 'Chiến lược bán Phi nhân thọ hiện tại đang giúp hay đang làm cản trở mục tiêu thu nhập dài hạn của các bạn?'","trait":"Coach"}]},{"id":13,"scenario":"Trong team có một TVV rất thuộc bài, tư vấn rất hay nhưng lại yếu khâu chốt Sales (Closing), luôn bị khách hàng nói 'Để anh suy nghĩ thêm'.","options":[{"text":"Cung cấp cho bạn ấy bộ 5 kịch bản chốt mặc định (Alternative Close, Assumptive Close) và bắt học thuộc lòng.","trait":"Architect"},{"text":"Tâm sự giải tỏa tâm lý sợ bị từ chối của bạn ấy, dặn bạn cứ làm bạn với khách trước, đừng áp lực chốt ngay.","trait":"Nurturer"},{"text":"Đi 'joint-work' (tư vấn chung) với bạn ấy 3 ca liên tiếp, trực tiếp thực hiện khâu chốt hợp đồng để bạn ấy quan sát.","trait":"Visionary"},{"text":"Sau mỗi ca rớt, hỏi: 'Lúc khách nói để suy nghĩ thêm, cảm xúc của em lúc đó thế nào? Lần sau em sẽ phản hồi lại câu gì?'","trait":"Coach"}]},{"id":14,"scenario":"Một khách hàng lớn có tiền sử bệnh lý phức tạp bị phòng Thẩm định của công ty từ chối bảo vệ. TVV của bạn rất phẫn nộ với bộ phận Thẩm định.","options":[{"text":"Yêu cầu TVV thu thập thêm chứng từ y tế chi tiết, tự mình soạn email giải trình gửi cấp quản lý Thẩm định để xem xét lại.","trait":"Architect"},{"text":"Xoa dịu TVV, đồng tình rằng quy trình đôi khi cứng nhắc, khuyên bạn ấy coi như thiếu may mắn và tập trung tệp khách khác.","trait":"Nurturer"},{"text":"Trực tiếp lên gặp Trưởng phòng Thẩm định để bảo vệ quyền lợi cho hồ sơ của team, thể hiện sự quyết liệt bảo vệ quân mình.","trait":"Visionary"},{"text":"Hỏi TVV: 'Ngoài việc tức giận, chúng ta còn cách nào khác để thương lượng với Thẩm định (vd: tăng phí, loại trừ) mà khách vẫn chấp nhận được?'","trait":"Coach"}]},{"id":15,"scenario":"Bạn đang bị quá tải: Vừa phải chạy số cá nhân để duy trì danh hiệu (MDRT), vừa phải quản lý, thúc đẩy một team 15 người.","options":[{"text":"Lập ma trận ưu tiên Eisenhower, phân bổ rõ 60% thời gian cho team, 40% cho cá nhân và tuân thủ kỷ luật lịch làm việc.","trait":"Architect"},{"text":"Nhờ cậy sự thông cảm của team, xin phép team tự vận hành vài ngày cuối tháng để mình chạy nước rút số cá nhân.","trait":"Nurturer"},{"text":"Cày cuốc 16 tiếng/ngày, lấy việc mình đạt MDRT làm cúp vinh quang để tạo động lực 'sếp làm được, lính làm được' cho team.","trait":"Visionary"},{"text":"Chọn ra 2 bạn TVV xuất sắc nhất trong team, trao quyền (delegate) cho họ hỗ trợ hướng dẫn các bạn mới thay mình.","trait":"Coach"}]}]$v81json$::jsonb,
  $v81json${"Visionary":{"name":"Người Tiên Phong (Visionary)","description":"Bạn dẫn dắt bằng năng lượng và sự lăn xả. Bạn là ngọn lửa kéo cả team đi lên trong những thời điểm kiệt sức nhất bằng cách làm gương.","goc_khuat":"Vì quá xông xáo, bạn dễ rơi vào bẫy 'làm thay' nhân viên. Điều này khiến tuyến dưới ỷ lại và bạn thì kiệt sức vì gánh vác quá nhiều.","goi_y_bao_boi":"Nhân Đôi Sức Mạnh Qua Người Khác","goi_y_roleplay":"Đóng vai: Hướng dẫn TVV tự lập kế hoạch tháng thay vì làm hộ."},"Architect":{"name":"Người Hoạch Định (Architect)","description":"Bạn dẫn dắt bằng lý trí, quy trình và sự chuẩn xác. Bạn giúp đội ngũ làm việc có hệ thống, quản lý phễu khách hàng tốt và không bị trượt mục tiêu.","goc_khuat":"Sự tập trung vào logic và con số đôi khi khiến bạn trở nên khô khan, cứng nhắc và vô tình bỏ qua những dấu hiệu mệt mỏi cảm xúc của team.","goi_y_bao_boi":"Đọc Vị Cảm Xúc Nội Bộ","goi_y_roleplay":"Đóng vai: Dùng khung SBI để lắng nghe một TVV đang kiệt sức."},"Nurturer":{"name":"Người Giữ Nhịp (Nurturer)","description":"Bạn là chất keo gắn kết đội ngũ. Bạn dùng sự thấu cảm để xoa dịu nỗi đau khi TVV bị từ chối và tạo ra một môi trường làm việc an toàn về tâm lý.","goc_khuat":"Vì sợ mất lòng và quá bao bọc, bạn thường né tránh việc kỷ luật mạnh tay hoặc ngại tạo áp lực doanh số trong những giai đoạn nước rút.","goi_y_bao_boi":"Dẻo Dai Trước Sóng Gió","goi_y_roleplay":"Đóng vai: Kỷ luật nghiêm túc một 'Ngôi sao' đang vi phạm nội quy."},"Coach":{"name":"Người Khai Vấn (Coach)","description":"Bạn không làm thay, mà giúp người khác tự lớn lên. Bằng những câu hỏi đúng, bạn khai phóng tiềm năng của tuyến dưới để họ tự xử lý những ca khó.","goc_khuat":"Phương pháp này tốn rất nhiều thời gian. Trong những tình huống 'cháy nhà' (khách hàng sắp hủy HĐ), bạn cần ra quyết định chớp nhoáng thay vì ngồi đặt câu hỏi.","goi_y_bao_boi":"Cách Nói Để Người Khác Thực Sự Hành Động (BLUF)","goi_y_roleplay":"Đóng vai: Chốt deal nhanh và áp đặt hợp lý ở phút 89."}}$v81json$::jsonb,
  true
)
on conflict (test_key) do update set
  intro_disclaimer = excluded.intro_disclaimer,
  questions = excluded.questions,
  results = excluded.results,
  is_active = excluded.is_active,
  updated_at = now();

-- Existing saved results keep their valid trait and receive the V81 canonical description.
update public.profiles as profile
set leadership_style_description = test.results -> profile.leadership_style ->> 'description'
from public.leadership_tests as test
where test.test_key = 'leadership_style_v1'
  and test.is_active = true
  and profile.leadership_style in ('Visionary', 'Architect', 'Nurturer', 'Coach');

commit;
